  if(file){st.textContent='Reading '+file.name+'…';const bytes=new Uint8Array(await file.arrayBuffer()),ext=(file.name.split('.').pop()||'').toLowerCase();
   if(ext==='pptx')text=await window.AtlasOffice.pptxText(bytes);else if(['txt','md'].includes(ext))text=new TextDecoder().decode(bytes);else text=(await sheetApi('ingest',{raw:bytes,headers:{'Content-Type':file.type||'application/octet-stream','x-file-name':file.name}})).text;
   if(['docx','pptx'].includes(ext))for(const im of await window.AtlasOffice.mediaImages(bytes)){const d=await toDataUrl(im.bytes,im.type);if(d)SS.images.push({name:im.name,...d});}}
  text=[text,$('sheetPaste').value.trim()].filter(Boolean).join('\n\n');
