  const draft=await sheetApi('draft',{body:{client:p.client,project:useInterview?interviewMaterial(p):{},current:filledOnly(p.sheet),documentText:text,answers:''}});
  saveSheet(p,E.mergeSheet(p.sheet,draft,text?'document':'interview'));SS.challenges=draft.challenges||[];E.log(p,'Reference sheet drafted from '+(text?'a document':'')+(text&&useInterview?' and ':'')+(useInterview?'the interview':''));
