// ---- Private memory (Hindsight, per person; the server derives the bank) ----
async function memoryApi(path,{method='GET',body}={}){const b=await bootInfo();if(!b.memory)throw Error('Memory is not configured here.');
 const r=await fetch('/api/memory'+path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json','X-Atlas-CSRF':b.csrf},body:body===undefined?undefined:JSON.stringify(body)});
 const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Memory did not answer.');return data;}
async function rememberInterview(p,transcript){try{const b=await bootInfo();if(!b.memory||p.sample)return;const r=await memoryApi('/remember',{method:'POST',body:{localId:p.id,...libraryPayload(p),conversation:String(transcript||'').slice(0,6000)}});if(r.stored)E.log(p,'Remembered privately for your next conversation');}catch{/* memory is best effort; the project is already saved */}}
async function renderMemoryPanel(){const b=await bootInfo(),panel=$('hindsightPanel');panel.hidden=!b.memory;if(!b.memory)return;$('connectionTest').hidden=b.libraryRole!=='admin';
 try{const m=await memoryApi('');$('memoryOn').checked=!m.off;const title=id=>{const local=id.replace(/^project-/,'');const p=profile().projects.find(x=>x.id===local);return id.startsWith('project-')?(p?p.title:'A project from another device'):id.startsWith('conversation-')?'Conversation on '+id.replace(/^conversation-.*-(\d{4})(\d{2})(\d{2})\d+$/,'$1-$2-$3'):id;};
  $('memoryList').innerHTML=m.documents.length?m.documents.map(d=>`<li><span>${esc(title(d.id))}${d.memories!==null?` <span class="tiny muted">· ${esc(d.memories)} memories</span>`:''}</span><button class="quiet" data-forget="${esc(d.id)}">Forget</button></li>`).join(''):'<li class="tiny muted">Nothing remembered yet.</li>';
  $('memoryStatus').textContent=m.off?'Memory is off: new conversations are not remembered.':'';}
 catch(e){$('memoryStatus').textContent=e.message;}}
$('memoryOn').onchange=async e=>{try{await memoryApi('/settings',{method:'POST',body:{off:!e.target.checked}});renderMemoryPanel();toast(e.target.checked?'ATLAS will remember your conversations.':'Memory is off.');}catch(err){toast(err.message);}};
$('memoryForgetAll').onclick=()=>confirm('Forget everything?','ATLAS permanently erases everything it remembers about your conversations. Your projects and the shared library are not affected.',async()=>{try{await memoryApi('/forget',{method:'POST',body:{all:true}});toast('Everything forgotten.');renderMemoryPanel();open('profileDialog');}catch(e){toast(e.message);}});
