const STATUS_LABEL={in_review:'In review',needs_work:'Needs work',changes_requested:'Changes requested',awaiting_validation:'Awaiting N+1',published:'Published',withdrawn:'Withdrawn'};
async function libraryApi(path,{method='GET',body}={}){const b=await bootInfo();if(!b.library)throw Error('The shared library is not available here.');
 const r=await fetch('/api/library'+path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json','X-Atlas-CSRF':b.csrf},body:body===undefined?undefined:JSON.stringify(body)});
 const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'The library did not answer.');return data;}
function libraryPayload(p){const sh=p.sheet;return {sheet:sh&&(sh.oppId||sh.title||Object.values(sh.sections).some(Boolean))?{oppId:sh.oppId,oppIdPending:sh.oppIdPending,title:sh.title,exec:sh.exec,sections:sh.sections,file:sh.file,fileName:sh.fileName,confirmedAt:sh.confirmedAt}:null,title:p.title,stage:p.stage,sector:p.sector,consultant:{name:p.consultant,role:p.role},client:p.client,details:p.details,answers:p.answers,report:p.report,jev:p.jev,
 validation:{manager:p.validation.manager,managerStaff:p.validation.managerStaff},sources:p.sources.map(s=>({name:s.name,version:s.version,url:s.url,excerpt:String(s.text||'').slice(0,1000)}))};}
async function syncToLibrary(id,{quiet=false}={}){const p=profile().projects.find(x=>x.id===id);if(!p||p.sample)return null;
 try{const r=await libraryApi('',{method:'POST',body:{localId:p.id,id:p.library?.id||undefined,reference:libraryPayload(p)}});p.library={id:r.id,revision:r.revision,status:r.status,syncedAt:E.now()};if(p.invitationId&&p.interview){libraryApi('/invitations/'+encodeURIComponent(p.invitationId),{method:'POST',body:{action:'done',referenceId:r.id}}).catch(()=>{});p.invitationId=null;}if(!r.unchanged)E.log(p,'Synced to the shared library (revision '+r.revision+')');save();if(view==='projects')renderProjects();if(!quiet)toast(r.unchanged?'Already up to date in the library.':'Saved to the shared library. The review agent is scoring it now.');return r;}
 catch(e){if(!quiet)toast(e.message);return null;}}
function libraryPill(p){if(!p.library)return '';return `<button class="quiet library-pill status-${esc(p.library.status)}" data-open-record="${esc(p.library.id)}">Library · ${esc(STATUS_LABEL[p.library.status]||p.library.status)} <span>r${esc(p.library.revision)}</span></button>`;}
